// Read API keys and user input from webhook body
const body = $json.body || {};
const GROQ_KEY = body.groq_api_key || '';
const FRAUD_KEY = body.anti_fraud_api_key || '';
const userText = body.text || '';
const hasImage = !!body.image_base64;

// Build Groq LLM prompt
const systemPrompt = `You are an anti-fraud analysis router. Analyze the user's message and extract:
1. Any URLs (http://, https://, or bare domains like example.com)
2. Any phone numbers (any format: +886..., 09..., 02-xxxx-xxxx, etc.)

Return ONLY valid JSON:
{
  "urls": ["https://example.com"],
  "phones": [{"country": "TW", "number": "+886289667000"}],
  "need_content_check": false,
  "summary": "brief description of what was found"
}

Rules:
- For Taiwan numbers without country code (e.g. 0289667000, 09xx), remove leading 0, prepend +886, set country to "TW"
- For URLs without protocol, prepend https://
- Always set need_content_check to false (content check is currently disabled)
- If nothing is found, return empty arrays
- ONLY return the JSON object, no markdown, no explanation`;

const groqBody = {
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userText }
  ],
  temperature: 0,
  max_tokens: 512,
  response_format: { type: 'json_object' }
};

// Call Groq API
let parsed;
try {
  const groqResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + GROQ_KEY,
      'Content-Type': 'application/json'
    },
    body: groqBody,
    json: true,
    timeout: 15000
  });
  const content = groqResp.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { urls: [], phones: [], need_content_check: false, summary: 'LLM error: ' + e.message };
}

return [{
  json: {
    urls: parsed.urls || [],
    phones: parsed.phones || [],
    need_content_check: false,
    summary: parsed.summary || '',
    original_text: userText,
    image_base64: null,
    anti_fraud_api_key: FRAUD_KEY
  }
}];

const data = $json;
const API_KEY = data.anti_fraud_api_key;
const BASE = 'https://hljaj2f6gf.execute-api.ap-northeast-1.amazonaws.com/prod';

const results = { url_results: [], number_results: [], content_result: null };
const self = this;

// --- URL Check (cache-first strategy) ---
for (let i = 0; i < data.urls.length; i++) {
  const url = data.urls[i];
  if (i > 0) await new Promise(r => setTimeout(r, 1100));
  try {
    // Try cache first
    let d;
    let usedCache = false;
    try {
      d = await self.helpers.httpRequest({
        method: 'POST',
        url: `${BASE}/url-check-cache`,
        headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json' },
        body: { url },
        json: true
      });
      usedCache = true;
    } catch (cacheErr) {
      // Cache miss (404) or stale (503) — fall back to full check
      await new Promise(r => setTimeout(r, 1100));
      d = await self.helpers.httpRequest({
        method: 'POST',
        url: `${BASE}/url-check`,
        headers: { 'x-api-key': API_KEY, 'Content-Type': 'application/json' },
        body: { url },
        json: true
      });
    }
    results.url_results.push({
      url, http_status: 200,
      score: d.score ?? null,
      score_status: d.score_status ?? null,
      domain: d.domain ?? url,
      blacklisted: d.blacklisted ?? null,
      cached: usedCache,
      registration_created: d.whois?.registration_created ?? null,
      registrant_country: d.whois?.registrant?.country ?? null,
      registrar_name: d.whois?.registrar?.name ?? null,
      ssl_valid: d.ssl?.valid ?? null,
      ssl_issuer: d.ssl?.issuer ?? null,
      phishing_count: d.antiphishing?.count ?? 0,
      threat_count: d.dnsblock?.threat?.count ?? 0,
      pageview: d.pageview ?? null,
      redirected_urls: d.redirected_urls ?? []
    });
  } catch (e) {
    results.url_results.push({ url, http_status: e.httpCode || e.status || e.statusCode || 0, error: e.message });
  }
}

// --- Number Check ---
for (let i = 0; i < data.phones.length; i++) {
  const phone = data.phones[i];
  if (i > 0) await new Promise(r => setTimeout(r, 1100));
  try {
    const d = await self.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/number-check/${phone.country}/${encodeURIComponent(phone.number)}`,
      headers: { 'x-api-key': API_KEY },
      json: true
    });
    results.number_results.push({
      number: phone.number, country: phone.country, http_status: 200,
      name: d.data?.name ?? null,
      region: d.data?.region ?? null,
      business_categories: d.data?.business_categories ?? [],
      spam_category: d.data?.spam_category ?? null
    });
  } catch (e) {
    results.number_results.push({ number: phone.number, country: phone.country, http_status: e.httpCode || e.status || e.statusCode || 0, error: e.message });
  }
}

// --- Content Check (currently disabled) ---
// Content check is temporarily disabled.
// To re-enable, uncomment the block below and set need_content_check logic in LLM Router.

// --- Build display text ---
const lines = [];
for (const u of results.url_results) {
  if (u.score != null) {
    lines.push(`URL: ${u.domain}`);
    lines.push(`- Score: ${u.score}/100`);
    lines.push(`- Blacklisted: ${u.blacklisted}`);
    lines.push(`- Cached: ${u.cached}`);
    lines.push(`- Registration Created: ${u.registration_created}`);
    lines.push(`- Registrant Country: ${u.registrant_country}`);
    lines.push(`- Registrar Name: ${u.registrar_name}`);
    lines.push(`- SSL Valid: ${u.ssl_valid} (Issuer: ${u.ssl_issuer})`);
    lines.push(`- Phishing Count: ${u.phishing_count}`);
    lines.push(`- Threat Block Count: ${u.threat_count}`);
    lines.push(`- Page Views: ${u.pageview}`);
    lines.push(`- Redirects: ${u.redirected_urls.length > 0 ? u.redirected_urls.join(', ') : 'None'}`);
  } else {
    lines.push(`URL ${u.url}: 查詢失敗 (HTTP ${u.http_status})`);
  }
}
for (const n of results.number_results) {
  lines.push(`Phone: ${n.number}`);
  lines.push(`- Real Name: ${n.name}`);
  lines.push(`- Region: ${n.region}`);
  lines.push(`- Business Categories: ${n.business_categories.join(', ')}`);
  lines.push(`- Spam Category: ${n.spam_category}`);
}
if (lines.length === 0) {
  lines.push('No URL or Phone number found.');
}

return [{
  json: {
    summary: data.summary,
    display_text: lines.join('\n'),
    url_results: results.url_results,
    number_results: results.number_results,
    content_result: null,
    original_text: data.original_text
  }
}];
